/* prog50_binary_heap.c
 *
 * Re‑implementation of the original program that was compiled,
 * then heavily obfuscated.  The observable behaviour (stdout) is
 * reproduced exactly.
 *
 * Behaviour:
 *   • If the program is invoked without any command‑line arguments
 *     it prints the single line
 *           NOOP
 *
 *   • Otherwise each argument is interpreted as a command:
 *
 *       I<number>   – insert the signed decimal integer <number>
 *                     into a min‑heap of capacity 15.
 *                     * If the heap is already full, prints
 *                           FULL
 *                     * If the number cannot be parsed, prints
 *                           ERR
 *                     * On successful insertion prints
 *                           INS %ld\n   (the inserted value)
 *
 *       M           – query the minimum element of the heap.
 *                     * If the heap is empty, prints
 *                           EMPTY
 *                     * Otherwise prints
 *                           MIN %ld\n   (the current minimum)
 *
 *       any other   – prints
 *                           ERR
 *
 *   The heap is a classic binary min‑heap stored in a static array
 *   `heap[15]`.  Insertions percolate the new element up to maintain
 *   the heap property.  No delete operation is required for the
 *   observed output.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define HEAP_CAPACITY 15

static long heap[HEAP_CAPACITY];
static int  size = 0;

/* Insert a value into the min‑heap.
 * Returns 0 on success, 1 if the heap is already full. */
static int heap_insert(long value)
{
    if (size >= HEAP_CAPACITY)
        return 1;                     /* FULL */

    /* place at the end and percolate up */
    int idx = size;
    heap[size++] = value;

    while (idx > 0) {
        int parent = (idx - 1) / 2;
        if (heap[parent] <= heap[idx])
            break;
        /* swap with parent */
        long tmp = heap[parent];
        heap[parent] = heap[idx];
        heap[idx] = tmp;
        idx = parent;
    }
    return 0;
}

/* Return the current minimum; caller must ensure size > 0. */
static long heap_min(void)
{
    return heap[0];
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        const char *cmd = argv[i];

        if (cmd[0] == 'I' && cmd[1] != '\0') {
            /* Attempt to parse the integer after the leading 'I' */
            char *endptr;
            long val = strtol(cmd + 1, &endptr, 10);

            if (endptr == cmd + 1) {          /* no digits were found */
                puts("ERR");
                continue;
            }

            if (heap_insert(val)) {
                puts("FULL");
            } else {
                printf("INS %ld\n", val);
            }
        }
        else if (strcmp(cmd, "M") == 0) {
            if (size == 0) {
                puts("EMPTY");
            } else {
                printf("MIN %ld\n", heap_min());
            }
        }
        else {
            puts("ERR");
        }
    }
    return 0;
}
